/**
 * Each marker is something ONLY an ungated and working route emits. A 401 body
 * carries none of them, and neither does a 500 — which is the point: the marker
 * discriminates "open" from "gated" AND from "broken".
 */
const PUBLIC_ROUTES: Array<{ name: string; method: string; path: string; body?: unknown; marker: string }> = [
  { name: 'GET /status/:walletAddress', method: 'GET', path: `/status/${WALLET}`, marker: 'exists' },
  { name: 'POST /challenge', method: 'POST', path: '/challenge', body: { walletAddress: WALLET }, marker: 'CIP-8' },
  { name: 'POST /verify', method: 'POST', path: '/verify', body: signed, marker: 'MINTED_WALLET_ACCESS_TOKEN' },
  { name: 'POST /authenticate', method: 'POST', path: '/authenticate', body: signed, marker: 'MINTED_WALLET_ACCESS_TOKEN' },
];

describe('KS-942 — the four public wallet routes stay open', () => {
  it.each(PUBLIC_ROUTES)('$name answers WITHOUT a bearer, and does the job', async ({ method, path, body, marker }) => {
    const r = await call(method, path, body);
    expect(r.status).not.toBe(401);
    // The marker, not merely the status: `not 401` is satisfied by a 500.
    expect(r.body).toContain(marker);
  });

  // CONTROLS. Without these the table above would pass against a stand-in that
  // never gates anything — i.e. against ks796's passthrough, which is exactly
  // the harness that could not see this defect.
  it('CONTROL — DELETE /unlink WITHOUT a bearer is 401, so the stand-in really gates', async () => {
    const r = await call('DELETE', '/unlink');
    expect(r.status).toBe(401);
  });

  it('CONTROL — POST /link WITHOUT a bearer is 401', async () => {
    const r = await call('POST', '/link', { walletAddress: WALLET });
    expect(r.status).toBe(401);
  });
});
